const input = $json.body ?? $json;
const truthy = v => v === true || v === "true" || v === 1 || v === "1";
const arr = v => Array.isArray(v) ? v : [];
const blockers = arr(input.blockers);
const requiredDocs = arr(input.required_documents);
const suppliedDocs = arr(input.supplied_documents);
const requiredMilestones = arr(input.required_milestones);
const completedMilestones = arr(input.completed_milestones);
const failedMilestones = arr(input.failed_milestones);
const recovery = input.recovery ?? {};
const readiness = input.transaction_readiness ?? {};

const identityComplete = Boolean(input.deal_id && input.lead_id && input.property_id);
const recoveryComplete = truthy(input.recovery_completed) || ["completed","recovered","resolved"].includes(String(recovery.status || "").toLowerCase());
const noActiveRecovery = !truthy(input.recovery_required) && !truthy(recovery.active) && !["pending","in_progress","failed","blocked"].includes(String(recovery.status || "").toLowerCase());
const milestonesComplete = requiredMilestones.length === 0 || requiredMilestones.every(req => completedMilestones.some(done => String(done.id ?? done) === String(req.id ?? req)));
const noFailedMilestones = failedMilestones.length === 0;
const docsComplete = requiredDocs.length === 0 || requiredDocs.every(req => suppliedDocs.some(doc => String(doc.id ?? doc) === String(req.id ?? req)));
const readinessComplete = truthy(input.transaction_ready) || ["ready","reconciled","transaction_ready"].includes(String(readiness.status || "").toLowerCase());
const blockersClear = blockers.length === 0;
const closingDate = input.closing_date ? new Date(input.closing_date) : null;
const closingDateValid = !input.closing_date || !Number.isNaN(closingDate.getTime());
const closingDateNotPassed = !closingDateValid || closingDate >= new Date();
const reconciliationReady = identityComplete && recoveryComplete && noActiveRecovery && milestonesComplete && noFailedMilestones && docsComplete && readinessComplete && blockersClear && closingDateValid;

let status = "reconciliation_required";
let nextWorkflow = "WF-276";
let humanReview = false;

if (!identityComplete) {
  status = "blocked_missing_identity";
  nextWorkflow = "WF-126";
  humanReview = true;
} else if (!recoveryComplete || !noActiveRecovery) {
  status = "recovery_incomplete";
  nextWorkflow = "WF-274";
  humanReview = true;
} else if (!noFailedMilestones || !milestonesComplete || !docsComplete) {
  status = "readiness_evidence_gap";
  nextWorkflow = "WF-275";
  humanReview = true;
} else if (!blockersClear || !closingDateValid) {
  status = "blocked";
  nextWorkflow = "WF-126";
  humanReview = true;
} else if (!readinessComplete) {
  status = "transaction_readiness_reconciliation_required";
  nextWorkflow = "WF-276";
  humanReview = true;
} else if (closingDateNotPassed && reconciliationReady) {
  status = "transaction_readiness_reconciled";
  nextWorkflow = "WF-276";
}

return [{
  json: {
    ...input,
    workflow: "WF-275",
    workflow_name: "Closing Recovery Completion → Transaction Readiness Reconciliation Controller",
    status,
    recovery_completion: {
      recovery_complete: recoveryComplete,
      no_active_recovery: noActiveRecovery,
      failed_milestones_clear: noFailedMilestones
    },
    reconciliation: {
      identity_complete: identityComplete,
      milestones_complete: milestonesComplete,
      required_documents_complete: docsComplete,
      blockers_clear: blockersClear,
      closing_date_valid: closingDateValid,
      closing_date_not_passed: closingDateNotPassed,
      transaction_readiness_complete: readinessComplete,
      reconciled: reconciliationReady
    },
    next_workflow: nextWorkflow,
    human_review_required: humanReview,
    routing_reason: status,
    audit: {
      event_type: "closing_recovery_completion_reconciliation",
      idempotency_key: input.idempotency_key || `wf-275:${input.deal_id || "unknown"}:${input.recovery_id || "none"}:${input.version || 1}`
    }
  }
}];
